-	u32 bit_mask, eorx;
+	u32 bit_mask, eorx, shift;
 	const char *s = image->data, *src;
 	u32 *dst;
 	const u32 *tab;
 	size_t tablen;
 	u32 colortab[16];
 	int i, j, k;

 	switch (bpp) {
 	case 8:
 		tab = fb_be_math(p) ? cfb_tab8_be : cfb_tab8_le;
 		tablen = 16;
 		break;
 	case 16:
