 		fgx <<= bpp;
 		bgx <<= bpp;
 		fgx |= fgcolor;
 		bgx |= bgcolor;
 	}

 	bit_mask = (1 << ppw) - 1;
 	eorx = fgx ^ bgx;
 	k = image->width/ppw;

 	for (i = 0; i < tablen; ++i)
 		colortab[i] = (tab[i] & eorx) ^ bgx;

 	for (i = image->height; i--; ) {
 		dst = dst1;
+		shift = 8;
 		src = s;

+		/*
+		 * Manually unroll the per-line copying loop for better
